from collections import deque

def find_clusters(grid):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    clusters = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2 and (r, c) not in visited:
                cluster = []
                queue = deque([(r, c)])
                visited.add((r, c))
                cluster.append((r, c))
                while queue:
                    curr_r, curr_c = queue.popleft()
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if (nr, nc) not in visited and 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == 2:
                                visited.add((nr, nc))
                                cluster.append((nr, nc))
                                queue.append((nr, nc))
                clusters.append(cluster)
    return clusters

def get_bar_row(cluster):
    rcounts = {}
    for r, cc in cluster:
        rcounts[r] = rcounts.get(r, 0) + 1
    maxr = max(rcounts.values())
    bars = [r for r, v in rcounts.items() if v == maxr]
